+  const client = createDashboardWebSocketClient(options);
+  
+  // Add message handlers
+  Object.entries(messageHandlers).forEach(([type, handler]) => {
+    if (handler) {
+      client.addMessageHandler(type as keyof TypedMessageHandlers, handler);
