+    for (const line of lines) {
+      if (line.includes(`## ${sectionName}`) || line.includes(`### ${sectionName}`)) {
+        inSection = true;
+        continue;
+      }
+
+      if (inSection) {
+        // Stop at next section
+        if (line.startsWith('## ') || line.startsWith('### ')) {
