+      }
+
+      if (inRegressionSection) {
+        // Stop at next section
+        if (line.startsWith('## ') || line.startsWith('### ')) {
+          break;
+        }
+
+        // Look for check items
+        const checkMatch = line.match(/[-•✅❌]\s+(.+)$/);
+        if (checkMatch?.[1]) {
+          checks.push(checkMatch[1].trim());
+        }
+      }
+    }
+
+    return checks;
+  }
