+  hash: string;
+  attempts: number;
+  lastAttempt: number;
+}
+
+interface RateLimitEntry {
+  count: number;
+  resetAt: number;
+}
+
+interface SessionEntry {
+  tunnelId: string;
+  createdAt: number;
+  expiresAt: number;
+}
