+  enforceReadOnly = async (req: FastifyRequest, reply: FastifyReply) => {
+    // Skip if not in read-only mode
+    if (!this._options.readOnlyMode) {
+      return;
+    }
+
+    // Allow GET requests and WebSocket connections
+    if (req.method === 'GET' || req.url === '/ws') {
+      return;
+    }
