+            this.name,
+            'NGROK_AUTH_REQUIRED',
+            'ngrok requires an auth token. Set NGROK_AUTHTOKEN environment variable or pass authToken in config'
+          );
+        }
+      } catch (error) {
+        if (error instanceof TunnelProviderError) {
+          throw error;
+        }
+        // If config check fails, we'll try to proceed anyway
+      }
+    }
+  }
