+
+export interface SpecChangeEvent {
+  type: 'added' | 'changed' | 'removed';
+  spec: string;
+  file: string;
+  data?: Spec | null;
+}
+
+export interface BugChangeEvent {
+  type: 'added' | 'changed' | 'removed';
+  bug: string;
+  file: string;
+  data?: Bug | null;
+}
+
+export interface GitChangeEvent {
+  type: 'branch-changed' | 'commit-changed';
+  branch?: string;
+  commit?: string;
