+
+export interface SteeringChangeEvent {
+  type: 'added' | 'changed' | 'removed';
+  file: string;
+  steeringStatus?: SteeringStatus;
+}
+
+export class SpecWatcher extends EventEmitter {
+  private watcher?: FSWatcher;
